    tour_logs_id,
    places_id
) VALUES

(
    (SELECT id FROM tour_logs
        WHERE tours_id = #{item.toursId}
        AND date = TO_DATE(#{item.tourLogDate}, 'DD/MM/YYYY')
    ),
    #{item.placesId}
)

ON CONFLICT (tour_logs_id, places_id)
DO NOTHING

